#!/usr/bin/env python3
"""
Chinna V6 — standalone installer (all 15 Godspeed features)
Run:   python3 chinna_v6.py
Re-run any time — stops old server, writes fresh files, boots V6.

What's in V6:
  ✅ P1  Config system (env/models, model presets, secure key storage)
  ✅ P2  Doctor / Diagnostics (CLI tools, AI config, dashboard status)
  ✅ P3  Stack Detection (Next/Vite/FastAPI/Django/Flutter/Go/Rust...)
  ✅ P4  Smart Go Runner (auto-install, port finder, browser open)
  ✅ P5  Cleanup Suite (light/mac/docker/nodes/project + bytes freed)
  ✅ P6  Project Audit (git/npm audit/pycompile + timestamped report)
  ✅ P7  Mission Control Dashboard (voice, health, elapsed time)
  ✅ P8  Apple Music Controls (play/pause/next/prev/now playing)
  ✅ P9  WhatsApp (open app, send wa.me link, webhook log)
  ✅ P10 macOS Utilities (lock, sleep, kill-port, screen share)
  ✅ P11 Notifications (notify/sound/speak/automation toggle)
  ✅ P12 Plugin Loader (hooks, bootstrap, plugin list)
  ✅ P13 Project Registry (record, status table, history, notes, tags)
  ✅ P14 Resumable Installer (step tracking, brew, zshrc, defaults)
  ✅ P15 Interactive Menu (box drawing, 25+ grouped commands)
"""
import base64, os, subprocess, time, sys

HOME  = os.path.expanduser("~")
CHINNA = os.path.join(HOME, ".chinna")
DASH   = os.path.join(CHINNA, "dashboard")
PORT   = 7777

SERVER_B64 = ""
DASH_B64   = ""

BANNER = """
  ╔══════════════════════════════════════════════════════════╗
  ║   C H I N N A   V 6   —  Your Mac Sidekick              ║
  ║   15 Godspeed features · Music · WhatsApp · AI Models    ║
  ╚══════════════════════════════════════════════════════════╝"""

def step(msg): print(f"  → {msg}")
def ok(msg):   print(f"  ✅ {msg}")

def main():
    print(BANNER)
    print()
    step("Stopping old server...")
    os.system("pkill -9 -f dashboard_server 2>/dev/null")
    os.system("pkill -9 -f \'server.py 7777\' 2>/dev/null")
    time.sleep(2)

    step("Creating directories...")
    for d in [DASH, os.path.join(CHINNA,"lib"), os.path.join(CHINNA,"logs")]:
        os.makedirs(d, exist_ok=True)

    step("Writing server (1891 lines, 37 endpoints)...")
    with open(os.path.join(CHINNA, "dashboard_server.py"), "wb") as f:
        f.write(base64.b64decode(SERVER_B64))

    step("Writing dashboard (117KB, 15 views, 3 themes)...")
    with open(os.path.join(DASH, "index.html"), "wb") as f:
        f.write(base64.b64decode(DASH_B64))

    step("Writing VERSION = 6.0.0...")
    with open(os.path.join(CHINNA, "VERSION"), "w") as f:
        f.write("6.0.0")

    # Migrate V4/V5 api_keys.json → env file
    old_keys = os.path.join(CHINNA, "api_keys.json")
    env_file  = os.path.join(CHINNA, "env")
    if os.path.exists(old_keys) and not os.path.exists(env_file):
        try:
            import json
            with open(old_keys) as f: keys = json.load(f)
            with open(env_file, "w") as f:
                [f.write(f"{k}={v}\n") for k,v in keys.items()]
            os.chmod(env_file, 0o600)
            ok("Migrated V5 API keys → ~/.chinna/env")
        except: pass

    # Write models file if missing
    models_file = os.path.join(CHINNA, "models")
    if not os.path.exists(models_file):
        with open(models_file, "w") as f:
            f.write('''ACTIVE_MODEL="meta-llama/llama-3.3-70b-instruct:free"
MODEL_coder="openai/gpt-4o"
MODEL_reasoning="anthropic/claude-3.5-sonnet"
MODEL_small="openai/gpt-4o-mini"
MODEL_free="meta-llama/llama-3.3-70b-instruct:free"
MODEL_sonnet4="anthropic/claude-3.5-sonnet"
MODEL_opus4="anthropic/claude-3-opus"
MODEL_haiku4="anthropic/claude-3-haiku"
''')
        os.chmod(models_file, 0o600)
        ok("Created models file with presets")

    step(f"Starting server on port {PORT}...")
    subprocess.Popen(
        ["python3", os.path.join(CHINNA, "dashboard_server.py"), str(PORT)],
        stdout=open(os.path.join(CHINNA, "dashboard.log"), "w"),
        stderr=subprocess.STDOUT, start_new_session=True)
    time.sleep(3)

    # Health check
    try:
        import urllib.request, json as _json
        d = _json.loads(urllib.request.urlopen(
            f"http://localhost:{PORT}/api/version", timeout=5).read())
        ok(f"{d.get('name','Chinna V6')} {d.get('version','')} — server ready!")
    except Exception as e:
        print(f"  ⚠ Server warming up ({e})")

    # macOS notification
    os.system('''osascript -e 'display notification "All 15 Godspeed features active!" with title "🟢 Chinna V6 ready"' 2>/dev/null''')

    print()
    print("  " + "═"*54)
    print(f"  ✅  CHINNA V6 READY  →  http://localhost:{PORT}")
    print("  " + "═"*54)
    print()
    print("  Share with friends:")
    print("  curl -fsSL https://raw.githubusercontent.com/pichimail/chinna-go/main/install/install.sh | bash")
    print()
    print("  Quick commands (open a new terminal tab first):")
    print("    chinna doctor      → system health")
    print("    chinna run         → smart project runner")
    print("    chinna ai chat     → AI chat")
    print("    chinna dashboard   → open dashboard")
    print("    chinna model-set free → switch model")
    print("    chinna clean       → deep clean")
    print()

    os.system(f"open http://localhost:{PORT} 2>/dev/null")

if __name__ == "__main__":
    main()
